// Used when a message has been successfully processed to report any warnings or business errors that occurred.
type Warning struct {
	// Unique identifier for the record.
	ID string `gorm:"column:id;primaryKey;not null" json:"id"`
	// Language identification. OTA: LanguageGroup/@Language.
	LanguageCode *string `gorm:"column:language_code" json:"language_code,omitempty"`
	// The Warning element MUST contain the Type attribute that uses a recommended set of values to indicate the warning type. The validating XSD can expect to accept values that it has NOT been explicitly coded for and process them by using Type ="Unknown". Refer to OpenTravel Code List Error Warning Type (EWT). Codes from the OpenTravel code table EWT; each value's number is its OTA code. OTA: WarningType/@Type.
	Type ErrorWarningType `gorm:"column:type;not null;default:'UNKNOWN';check:chk_warnings_type,type IN ('UNKNOWN','NO_IMPLEMENTATION','BIZ_RULE','AUTHENTICATION','AUTHENTICATION_TIMEOUT','AUTHORIZATION','PROTOCOL_VIOLATION','TRANSACTION_MODEL','AUTHENTICAL_MODEL','REQUIRED_FIELD_MISSING','ADVISORY','PROCESSING_EXCEPTION','APPLICATION_ERROR')" json:"type" validate:"required"`
	// An abbreviated version of the error in textual format. OTA: ErrorWarningAttributeGroup/@ShortText.
	ShortText *string `gorm:"column:short_text" json:"short_text,omitempty"`
	// If present, this refers to a table of coded values exchanged between applications to identify errors or warnings. Refer to OpenTravel Code List Error Codes (ERR). An OpenTravel code; OTA does not say which code table it is from. OTA: ErrorWarningAttributeGroup/@Code.
	Code *string `gorm:"column:code" json:"code,omitempty"`
	// If present, this URL refers to an online description of the error that occurred. OTA: ErrorWarningAttributeGroup/@DocURL.
	DocURI *string `gorm:"column:doc_uri" json:"doc_uri,omitempty"`
	// If present, recommended values are those enumerated in the OTA_ErrorRS, (NotProcessed | Incomplete | Complete | Unknown) however, the data type is designated as string data, recognizing that trading partners may identify additional status conditions not included in the enumeration. OTA: ErrorWarningAttributeGroup/@Status.
	Status *string `gorm:"column:status" json:"status,omitempty"`
	// If present, this attribute may identify an unknown or misspelled tag that caused an error in processing. It is recommended that the Tag attribute use XPath notation to identify the location of a tag in the event that more than one tag of the same name is present in the document. Alternatively, the tag name alone can be used to identify missing data [Type=ReqFieldMissing]. OTA: ErrorWarningAttributeGroup/@Tag.
	Tag *string `gorm:"column:tag" json:"tag,omitempty"`
	// If present, this attribute allows for batch processing and the identification of the record that failed amongst a group of records. This value may contain a concatenation of a unique failed transaction ID with specific record(s) associated with that transaction. OTA: ErrorWarningAttributeGroup/@RecordID.
	RecordID *string `gorm:"column:record_id" json:"record_id,omitempty"`
	// Reference Place Holder used as an index for this warning. OTA: WarningType/@RPH.
	Rph *string `gorm:"column:rph" json:"rph,omitempty"`
	// The element's text. OTA: WarningType/#text.
	Value *string `gorm:"column:value" json:"value,omitempty"`
	// Back-relation: EncryptionToken records that reference this via warning_id.
	EncryptionTokens []EncryptionToken `gorm:"foreignKey:WarningID" json:"encryptiontokens,omitempty"`
}

